<template>
  <section><header class="mb-4"><h1 class="page-title">Khóa học của tôi</h1><p class="page-subtitle">Theo dõi và tiếp tục các khóa học đã ghi danh.</p></header><div class="app-card p-3 mb-4"><div class="row g-2"><div class="col-md-8"><input v-model="search" class="form-control" placeholder="Tìm theo tên khóa học hoặc giảng viên..."></div><div class="col-md-4"><select v-model="status" class="form-select"><option value="">Tất cả trạng thái</option><option value="PUBLISHED">Đang học</option><option value="DRAFT">Sắp mở</option></select></div></div></div><div class="row g-4"><div v-for="course in filtered" :key="course.id" class="col-md-6 col-xl-4"><article class="course-card app-card h-100"><div class="course-art" :style="{background:course.color}"><i class="bi bi-code-square"></i><span>{{ course.code }}</span></div><div class="p-3"><span class="badge badge-soft-primary">{{ course.category }}</span><h2>{{ course.title }}</h2><p><i class="bi bi-person me-1"></i>{{ course.teacher }}</p><div class="d-flex justify-content-between small"><span>{{ course.lessons }} bài học</span><b>{{ course.progress }}%</b></div><div class="progress my-2" style="height:7px"><div class="progress-bar" :style="{width:course.progress+'%'}"></div></div><RouterLink :to="`/lms/courses/${course.id}`" class="btn btn-brand w-100 mt-2">Xem khóa học</RouterLink></div></article></div></div></section>
</template>
<script setup>
import { computed,ref } from 'vue'; import { courses } from '../../data/demo'; const search=ref(''),status=ref('');const filtered=computed(()=>courses.filter(c=>(!status.value||c.status===status.value)&&(`${c.title} ${c.teacher}`.toLowerCase().includes(search.value.toLowerCase()))))
</script>
